#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    int64 p;
    cin >> n >> m >> p;

    auto modPow = [&](int64 a, int64 e) {
        int64 result = 1;
        while (e > 0) {
            if (e & 1) result = result * a % p;
            a = a * a % p;
            e >>= 1;
        }
        return result;
    };

    vector<int64> fact(m + 1), invFact(m + 1);
    fact[0] = 1;
    for (int i = 1; i <= m; ++i)
        fact[i] = fact[i - 1] * i % p;

    invFact[m] = modPow(fact[m], p - 2);
    for (int i = m; i >= 1; --i)
        invFact[i - 1] = invFact[i] * i % p;

    vector<int64> f(m + 1), g(m + 1);
    f[0] = 1;

    int64 pow2 = 1;
    for (int k = 1; k <= m; ++k) {
        pow2 = pow2 * 2 % p;
        f[k] = pow2 * modPow(k + 1, k - 1) % p * invFact[k] % p;
    }

    for (int k = 1; k <= m; ++k) {
        int64 sumGF = 0;
        int64 sumTF = 0;

        for (int i = 0; i < k; ++i) {
            int j = k - 1 - i;

            sumGF = (sumGF + g[i] * f[j]) % p;

            int64 triangular = (int64)i * (i + 1) / 2 % p;
            int64 term = triangular * f[i] % p * f[j] % p;
            sumTF = (sumTF + term) % p;
        }

        int64 invK = fact[k - 1] * invFact[k] % p;
        int64 first = 2LL * (k + 1) % p * invK % p * sumGF % p;
        int64 second = 2LL * invK % p * sumTF % p;
        g[k] = (first + second) % p;
    }

    auto coefficientOfPower = [&](int s, int r) -> int64 {
        if (r == 0) return 1;
        if (s == 0) return 0;

        int64 twoPower = modPow(2, r);
        int64 treePower = modPow(s + r, r - 1);
        return twoPower * s % p * treePower % p * invFact[r] % p;
    };

    int h = n - m + 1;
    int s = h - 1;
    int64 answer = 0;

    for (int k = 1; k <= m; ++k) {
        int r = m - k;
        answer = (answer + g[k] * coefficientOfPower(s, r)) % p;
    }

    answer = answer * h % p * fact[m] % p;
    cout << answer << '\n';

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    int64 p;
    cin >> n >> m >> p;

    vector<int64> inv(m + 1), f(m + 1), g(m + 1);
    inv[1] = 1;
    for (int i = 2; i <= m; ++i) {
        inv[i] = (p - (p / i) * inv[p % i] % p) % p;
    }

    f[0] = 1;
    g[0] = 0;

    for (int s = 1; s <= m; ++s) {
        int64 sumF = 0;
        int64 sumG = 0;

        for (int l = 0; l < s; ++l) {
            int r = s - 1 - l;

            sumF += f[l] * f[r] % p;
            if (sumF >= p) sumF -= p;

            int64 previous =
                (g[l] * f[r] % p + f[l] * g[r] % p) % p;

            int64 triL = 1LL * l * (l + 1) / 2 % p;
            int64 triR = 1LL * r * (r + 1) / 2 % p;
            int64 added =
                f[l] * f[r] % p * ((triL + triR) % p) % p;

            int64 term = ((s + 1LL) * previous + added) % p;
            sumG += term;
            if (sumG >= p) sumG -= p;
        }

        f[s] = sumF * (s + 1LL) % p * inv[s] % p;
        g[s] = sumG * inv[s] % p;
    }

    vector<vector<int64>> dpF(m + 1, vector<int64>(m + 1));
    vector<vector<int64>> dpG(m + 1, vector<int64>(m + 1));
    dpF[0][0] = 1;

    for (int runs = 0; runs < m; ++runs) {
        for (int used = runs; used <= m; ++used) {
            int64 curF = dpF[runs][used];
            int64 curG = dpG[runs][used];
            if (curF == 0 && curG == 0) continue;

            for (int len = 1; used + len <= m; ++len) {
                int nt = used + len;

                int64 addF = curF * f[len] % p;
                dpF[runs + 1][nt] += addF;
                if (dpF[runs + 1][nt] >= p)
                    dpF[runs + 1][nt] -= p;

                int64 addG =
                    (curG * f[len] % p + curF * g[len] % p) % p;
                dpG[runs + 1][nt] += addG;
                if (dpG[runs + 1][nt] >= p)
                    dpG[runs + 1][nt] -= p;
            }
        }
    }

    vector<int64> fact(n + 1), invFact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i)
        fact[i] = fact[i - 1] * i % p;

    auto modPow = [&](int64 base, int64 exp) {
        int64 result = 1;
        while (exp > 0) {
            if (exp & 1) result = result * base % p;
            base = base * base % p;
            exp >>= 1;
        }
        return result;
    };

    invFact[n] = modPow(fact[n], p - 2);
    for (int i = n; i >= 1; --i)
        invFact[i - 1] = invFact[i] * i % p;

    auto binom = [&](int N, int K) -> int64 {
        if (K < 0 || K > N) return 0;
        return fact[N] * invFact[K] % p * invFact[N - K] % p;
    };

    int availableGaps = n - m + 1;
    int64 answer = 0;

    for (int runs = 1; runs <= m && runs <= availableGaps; ++runs) {
        int64 placements = binom(availableGaps, runs);
        answer = (answer + placements * dpG[runs][m]) % p;
    }

    answer = answer * fact[m] % p;
    cout << answer << '\n';

    return 0;
}

