        long long sf = 0, sg = 0, sq = 0;

        for (int l = 0; l < k; ++l) {
            int r = k - 1 - l;

            long long ff = f[l] * f[r] % p;
            sf += ff;
            if (sf >= p) sf -= p;

            long long term = (g[l] * f[r] + f[l] * g[r]) % p;
            sg += term;
            if (sg >= p) sg -= p;

            long long q = 1LL * l * (l + 1) / 2
                        + 1LL * r * (r + 1) / 2;
            sq = (sq + (q % p) * ff) % p;
        }

        f[k] = (k + 1LL) * sf % p * inv[k] % p;
        g[k] = ((k + 1LL) * sg + sq) % p * inv[k] % p;
    }

    auto multiply = [&](const vector<long long>& a,
                        const vector<long long>& b) {
        vector<long long> c(m + 1, 0);
        for (int i = 0; i <= m; ++i) {
            if (a[i] == 0) continue;
            for (int j = 0; i + j <= m; ++j) {
                if (b[j] == 0) continue;
                c[i + j] = (c[i + j] + a[i] * b[j]) % p;
            }
        }
        return c;
    };

    int exponent = n - m;
    vector<long long> power(m + 1, 0), base = f;
    power[0] = 1;

    while (exponent > 0) {
        if (exponent & 1) power = multiply(power, base);
        exponent >>= 1;
        if (exponent) base = multiply(base, base);
    }

    long long coefficient = 0;
    for (int k = 1; k <= m; ++k) {
        coefficient = (coefficient + g[k] * power[m - k]) % p;
    }

    coefficient = coefficient * (n - m + 1LL) % p;

    long long factorial = 1;
    for (int i = 1; i <= m; ++i) {
        factorial = factorial * i % p;
    }

    cout << factorial * coefficient % p << '\n';
    return 0;
}

