int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    int64 p;
    cin >> n >> m >> p;

    vector<int64> inv(m + 1), A(m + 1), B(m + 1);
    inv[1] = 1;
    for (int i = 2; i <= m; ++i)
        inv[i] = (p - (p / i) * inv[p % i] % p) % p;

    A[0] = 1;

    for (int k = 1; k <= m; ++k) {
        int64 sumA = 0, sumB = 0;

        for (int l = 0; l < k; ++l) {
            int r = k - 1 - l;
            int64 product = A[l] * A[r] % p;

            sumA += product;
            if (sumA >= p) sumA -= p;

            int64 previous = (B[l] * A[r] + A[l] * B[r]) % p;
            int64 q = ((int64)l * (l + 1) / 2 +
                       (int64)r * (r + 1) / 2) % p;

            int64 term = ((int64)(k + 1) * previous + q * product) % p;
            sumB += term;
            if (sumB >= p) sumB -= p;
        }

        A[k] = (int64)(k + 1) * sumA % p * inv[k] % p;
        B[k] = sumB * inv[k] % p;
    }

    auto multiply = [&](const vector<int64>& x,
                        const vector<int64>& y) {
        vector<int64> result(m + 1, 0);
        for (int i = 0; i <= m; ++i) {
            if (x[i] == 0) continue;
            for (int j = 0; i + j <= m; ++j) {
                if (y[j] == 0) continue;
                result[i + j] =
                    (result[i + j] + x[i] * y[j]) % p;
            }
        }
        return result;
    };

    int exponent = n - m;
    vector<int64> power(m + 1, 0), base = A;
    power[0] = 1;

    while (exponent > 0) {
        if (exponent & 1)
            power = multiply(power, base);
        exponent >>= 1;
        if (exponent)
            base = multiply(base, base);
    }

    int64 coefficient = 0;
    for (int k = 1; k <= m; ++k)
        coefficient = (coefficient + B[k] * power[m - k]) % p;

    int64 factorial = 1;
    for (int i = 2; i <= m; ++i)
        factorial = factorial * i % p;

    int64 answer = coefficient * (n - m + 1LL) % p;
    answer = answer * factorial % p;

    cout << answer << '\n';
    return 0;
}

#include <iostream>
#include <vector>
using namespace std;

using int64 = long long;

int64 modPow(int64 a, int64 e, int64 mod) {
    int64 result = 1;
    while (e > 0) {
        if (e & 1) result = result * a % mod;
        a = a * a % mod;
        e >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    int64 p;
    cin >> n >> m >> p;

    vector<int64> fact(m + 1), invFact(m + 1);
    fact[0] = 1;
    for (int i = 1; i <= m; ++i)
        fact[i] = fact[i - 1] * i % p;

    invFact[m] = modPow(fact[m], p - 2, p);
    for (int i = m; i >= 1; --i)
        invFact[i - 1] = invFact[i] * i % p;

    int64 k = (n + 1) % p;
    vector<int64> expCoeff(m + 1);
    int64 power = 1;
    for (int i = 0; i <= m; ++i) {
        expCoeff[i] = power * invFact[i] % p;
        power = power * k % p;
    }

    const int64 inv2 = (p + 1) / 2;

    auto coefficient = [&](int d, int type) -> int64 {
        if (d < 0) return 0;

        int64 result = 0;
        for (int j = 0; j <= d; ++j) {
            int64 multiplier;
            if (type == 2) {
                multiplier = j + 1;
            } else {
                multiplier = static_cast<int64>(j + 1) * (j + 2) % p;
                multiplier = multiplier * inv2 % p;
            }
            result = (result + multiplier * expCoeff[d - j]) % p;
        }
        return result;
    };

    int64 q = n - m + 1;
    int64 inner = 0;
    inner = (inner + q % p * coefficient(m - 3, 2)) % p;
    inner = (inner + 2 * coefficient(m - 2, 2)) % p;
    inner = (inner + 2 * coefficient(m - 3, 3)) % p;

    int64 answer = fact[m];
    answer = answer * modPow(2, m, p) % p;
    answer = answer * modPow(m, p - 2, p) % p;
    answer = answer * (q % p) % p;
    answer = answer * inv2 % p;
    answer = answer * inner % p;

    cout << answer << '\n';
    return 0;
}
